	@ParameterizedTest(name = "graph addAll source={0}")
	@MethodSource("graphFrameAddAllCases")
	void addAllTransfersGraphFrameOnlyForAnActualSourceWrite(String scenario, boolean boundSource,
			boolean suppliedTarget, boolean expectedSupplied, Set<String> expectedNames) {
		Projection lowering = new Projection(new SingletonSet());
		lowering.setProjectionContext(Var.of("callerGraph"));
		lowering.setInheritedGraphParameter("privateGraph");
		MapBindingSet caller = new MapBindingSet();
		caller.addBinding("callerGraph", OLD);
		BindingSet supplied = ProjectionQueryEvaluationStep.withInheritedGraphInput(lowering, caller,
				new QueryEvaluationContext.Minimal((Dataset) null));
		assertTrue(GraphFrameBindings.isSupplied(supplied, "privateGraph"),
				"the source frame comes from actual SELECT graph-input lowering");
		QueryBindingSet hidden = new QueryBindingSet();
		hidden.setBinding("payload", OLD);
		BindingSet narrowed = GraphFrameBindings.preserve(supplied, hidden);
		assertTrue(GraphFrameBindings.from(narrowed).retainedParametersForTransport().containsKey("privateGraph"));
		assertFalse(narrowed.hasBinding("privateGraph"),
				"the narrowed row retains graph metadata without a mapping write");

		BindingSet source = narrowed;
		if (boundSource) {
			QueryBindingSet mapped = new QueryBindingSet();
			GraphFrameBindings.supply(mapped, "privateGraph", OLD);
			source = mapped;
		}
		QueryBindingSet target = new QueryBindingSet();
		target.setBinding("privateGraph", OLD);
		if (suppliedTarget) {
			GraphFrameBindings.supply(target, "privateGraph", OLD);
		}
		assertEquals(suppliedTarget, GraphFrameBindings.isSupplied(target, "privateGraph"));
		target.addAll(source);
		assertSame(OLD, target.getValue("privateGraph"));
		assertEquals(expectedSupplied, GraphFrameBindings.isSupplied(target, "privateGraph"),
				"metadata-only source frames must not qualify an equal-valued target mapping");
		assertEquals(expectedNames, target.getBindingNames());
	}

	@ParameterizedTest(name = "request parameter addAll source has mapping={0}")
	@MethodSource("requestParameterAddAllCases")
	void addAllDoesNotReplaceARequestParameterWithoutWritingItsName(boolean sourceWritesParameter) {
		BindingSet targetInput = BindingSetOrigin.optimizationInput(request("parameter", OLD));
		QueryBindingSet target = new QueryBindingSet(targetInput);
		target.setBinding("occupied", PAYLOAD);
		assertSame(OLD, BindingSetOrigin.of(target).parameterValue("parameter"));

		BindingSet sourceInput = BindingSetOrigin.optimizationInput(request("parameter", NEW));
		QueryBindingSet source = new QueryBindingSet(sourceInput);
		source.setBinding("payload", PAYLOAD);
		if (sourceWritesParameter) {
			source.setBinding("parameter", NEW);
		}
		assertEquals(sourceWritesParameter, source.hasBinding("parameter"));
		assertSame(NEW, BindingSetOrigin.of(source).parameterValue("parameter"));
		QueryBindingSet fullCopy = new QueryBindingSet(source);
		assertSame(NEW, BindingSetOrigin.of(fullCopy).parameterValue("parameter"),
				"the copy constructor preserves the complete source frame");

		target.addAll(source);
		assertSame(sourceWritesParameter ? NEW : OLD, BindingSetOrigin.of(target).parameterValue("parameter"),
				"an overlay may change request authority only for a name actually written by the source");
		assertEquals(sourceWritesParameter, target.hasBinding("parameter"));
		assertEquals(sourceWritesParameter ? NEW : null, target.getValue("parameter"));
		assertTrue(BindingSetOrigin.of(target).isRequest("parameter"));
	}

	@Test
	void aMappedRequestWithoutRetainedValueCannotReenterAnOlderTargetParameter() {
		QueryBindingSet target = new QueryBindingSet(BindingSetOrigin.optimizationInput(request("parameter", OLD)));
		target.setBinding("payload", PAYLOAD);
		QueryBindingSet mappedRequest = new QueryBindingSet(BindingSetOrigin.requestInput(request("parameter", NEW)));
		assertTrue(BindingSetOrigin.of(mappedRequest).isRequest("parameter"));
		assertSame(null, BindingSetOrigin.of(mappedRequest).parameterValue("parameter"),
				"requestInput carries mapping authority without a hidden re-entry value");

		target.addAll(mappedRequest);

		BindingSet reentry = BindingScopeAnalysis.retain(target, Set.of());
		BindingSet afterMaterialization = BindingSetOrigin.materializeParameters(reentry,
				List.of(Var.of("parameter", OLD, false, false)), new QueryEvaluationContext.Minimal((Dataset) null));
		assertFalse(afterMaterialization.hasBinding("parameter"),
				"a new mapped request must not resurrect the overwritten hidden parameter from the target");
	}

	@ParameterizedTest(name = "first overwrite origin {0}")
	@ValueSource(strings = { "LOCAL", "UNKNOWN" })
	void nonRequestOverwriteCannotLeaveAHiddenParameterThatLaterRequestCanRevive(String firstWriteOrigin) {
		QueryBindingSet target = new QueryBindingSet(BindingSetOrigin.optimizationInput(request("parameter", OLD)));
		QueryBindingSet firstWrite = new QueryBindingSet();
		firstWrite.setBinding("parameter", NEW);
		if (firstWriteOrigin.equals("LOCAL")) {
			BindingSetOrigin.set(firstWrite, BindingSetOrigin.of(firstWrite).producing(Set.of("parameter")));
		}
		target.addAll(firstWrite);
		assertSame(NEW, target.getValue("parameter"));
		assertFalse(BindingSetOrigin.of(target).isRequest("parameter"));

		QueryBindingSet laterRequest = new QueryBindingSet(BindingSetOrigin.requestInput(request("parameter", NEW)));
		target.addAll(laterRequest);
		BindingSet reentry = BindingScopeAnalysis.retain(target, Set.of());
		BindingSet afterMaterialization = BindingSetOrigin.materializeParameters(reentry,
				List.of(Var.of("parameter", OLD, false, false)), new QueryEvaluationContext.Minimal((Dataset) null));
		assertFalse(afterMaterialization.hasBinding("parameter"),
				"a local/unknown write must evict the older hidden value before a later request-origin write");
	}

