	@Test
	void schemaOnlyRequestEntryDoesNotReplaceTrackedDormantRequestParameter() {
		QueryBindingSet target = new QueryBindingSet(BindingSetOrigin.optimizationInput(request("marker", OLD)));
		target.setBinding("payload", PAYLOAD);
		ListBindingSet schemaOnly = new ListBindingSet(List.of("payload", "marker"), PAYLOAD, null);
		BindingSet requestEntry = BindingSetOrigin.requestInput(schemaOnly);
		assertTrue(BindingSetOrigin.of(requestEntry).isRequest("payload"));
		assertFalse(BindingSetOrigin.of(requestEntry).isRequest("marker"),
				"the UNDEF header is not a request mapping");
		assertFalse(requestEntry.hasBinding("marker"));

		target.addAll(requestEntry);
		assertFalse(target.hasBinding("marker"), "addAll does not materialize or overwrite a schema-only slot");
		assertSame(OLD, BindingSetOrigin.of(target).parameterValue("marker"),
				"the accepted payload write leaves the target's independently tracked dormant marker intact");
		BindingSet reentry = BindingScopeAnalysis.retain(target, Set.of());
		BindingSet materialized = BindingSetOrigin.materializeParameters(reentry,
				List.of(Var.of("marker", OLD, false, false)), new QueryEvaluationContext.Minimal((Dataset) null));
		assertSame(OLD, materialized.getValue("marker"),
				"a later producer re-entry may still use the target's genuine dormant request value");
	}

